  "findings": [
    {
      "benefit": "Death",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "Empirical AE SD ≈0.18 vs Poisson 1/sqrt(E) ≈0.04-0.06, i.e. roughly 3-5x overdispersed; AE range 0.723 to 1.322 with unchanged overall level ≈1.001",
      "confidence": 0.75,
      "evidence": [
        "ae_death_by_year.csv: AE moves from 1.170 in 2016 to 1.322 in 2017, drops to 0.837 in 2018, falls to 0.723 in 2021, and rises to 1.106/1.126 in 2023/2024",
        "simple empirical SD of Death AE over 2015-2024 is ≈0.184, materially above Poisson AE dispersion of ≈1/sqrt(expected claims), which declines from ≈0.065 in 2015 to ≈0.035 in 2024",
        "summary.json: Death overall_ae=1.001 with 5005 claims, indicating the long-run level is near baseline but year-to-year experience is overdispersed"
      ],
      "recommended_action": "Review Death data quality and the expected mortality basis, including exposure, age/gender mix, claim dates, late/large claims, and possible reporting or valuation-basis issues. Avoid using Poisson z-scores for individual Death years; model overdispersion in stochastic testing and reassess mortality pricing/valuation assumptions if this volatility reflects genuine experience rather than data error."
    }
  ]
}

